/** A small stable hash, so the shuffle does not change between loads. */
const hash = (text: string): number => {
  let h = 7;
  for (let i = 0; i < text.length; i += 1) h = (h * 31 + text.charCodeAt(i)) % 1000003;
  return h;
};

/** Moves the first item (the answer) into a stable position derived from the seed. */
const place = <T,>(answerFirst: T[], seed: string): { items: T[]; answerIndex: number } => {
  const [answer, ...rest] = answerFirst;
  const answerIndex = hash(seed) % answerFirst.length;
  rest.splice(answerIndex, 0, answer);
  return { items: rest, answerIndex };
};

export const VOCAB_PRACTICE: VocabPractice[] = RAW.map(
  ([word, simplerSentence, simplerOptions, usageRight, usageWrong, blankSentence, blankOptions]) => {
    const simpler = place(simplerOptions, `${word}:simpler`);
    const usage = place([usageRight, ...usageWrong], `${word}:usage`);
    const blank = place(blankOptions, `${word}:blank`);
    return {
      word,
      simpler: { sentence: simplerSentence, options: simpler.items, answerIndex: simpler.answerIndex },
      usage: { sentences: usage.items, answerIndex: usage.answerIndex },
      blank: { sentence: blankSentence, options: blank.items, answerIndex: blank.answerIndex },
    };
  },
);
